    parameter A = 1'b0, B = 1'b1, C = 1'b10, D = 1'b11;

    reg [1:0] state;

    always @(posedge clk)
        case (state)
            A: begin
                if (x == 0 && y == 0) state <= A;
                else if (x == 0 && y == 1) state <= D;
                else if (x == 1 && y == 0) state <= B;
                else if (x == 1 && y == 1) state <= C;
            end
            B: begin
                if (x == 0 && y == 0) state <= A;
                else if (x == 0 && y == 1) state <= D;
                else if (x == 1 && y == 0) state <= B;
                else if (x == 1 && y == 1) state <= C;
            end
            C: begin
                if (x == 0 && y == 0) state <= A;
                else if (x == 0 && y == 1) state <= D;
                else if (x == 1 && y == 0) state <= B;
                else if (x == 1 && y == 1) state <= C;
            end
            D: begin
                if (x == 0 && y == 0) state <= A;
                else if (x == 0 && y == 1) state <= D;
                else if (x == 1 && y == 0) state <= B;
                else if (x == 1 && y == 1) state <= C;
            end
        endcase

    assign z = (state == C);

